import sys


def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    m = int(input_data[1])

    words = []
    for i in range(m):
        num = i
        chars = []
        while True:
            chars.append(chr(ord("a") + num % 26))
            num //= 26
            if num == 0:
                break
        words.append("".join(chars))

    print(" ".join(words))


if __name__ == "__main__":
    main()
